export class ServerTransport {
    #cometd;

    constructor(cometd) {
        this.#cometd = cometd;
    }

    get cometd() {
        return this.#cometd;
    }

    option(name) {
        let dftValue = undefined;
        switch (name) {
            case "interval":
                dftValue = 0;
                break;
            case "maxInterval":
                dftValue = 10000;
                break;
            case "timeout":
                dftValue = 20000;
                break;
        }
        return this._option("", name, dftValue);
    };

    _option(prefix, name, dftValue) {
        const options = this.#cometd.options;
        let result = options[name];
        const segments = prefix.split(".");
        let pfx = null;
        for (let i = 0; i < segments.length; ++i) {
            const segment = segments[i];
            pfx = pfx === null ? segment : pfx + "." + segment;
            const key = pfx + "." + name;
            const value = options[key];
            if (value !== undefined) {
                result = value;
            }
        }
        if (result === undefined) {
            result = dftValue;
        }
        return result;
    };
}
